/**
 * Read an amount of bytes at a given offset from a copy-on-write
 * export. At most a single DIFFPAGESIZE-sized block is read: from the
 * diff file if the block has been written during this connection,
 * from the master file otherwise.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error.
 **/
ssize_t rawexpcowread(off_t a, char *buf, size_t len, CLIENT *client) {
	off_t blockoff = a % DIFFPAGESIZE;
	uint64_t block = a / DIFFPAGESIZE;
	off_t *slot;
	ssize_t retval;

	if(len > (size_t)(DIFFPAGESIZE - blockoff))
		len = DIFFPAGESIZE - blockoff;

	pthread_rwlock_rdlock(&client->export_lock);
	slot = g_hash_table_lookup(client->diffmap, &block);
	pthread_rwlock_unlock(&client->export_lock);
	if(!slot)
		return rawexpread(a, buf, len, client);

	DEBUG("(READ from diff fd %d offset %llu len %u), ", client->difffile, (unsigned long long)(*slot + blockoff), (unsigned int)len);
	retval = pread(client->difffile, buf, len, *slot + blockoff);
	return retval;
}
```

