/**
 * Look up the offset at which a given block is stored in the diff
 * file, allocating a slot for it if it is not there yet. If the block
 * is dirty already, no new slot is allocated.
 *
 * Must be called with the export lock held for writing.
 *
 * @param client The client we're serving for
 * @param block The block number to look up
 * @param full Whether the caller is about to overwrite the whole
 * block, in which case the original data does not need to be copied
 * @return The offset of the block in the diff file, or -1 on error
 **/
static off_t cow_get_slot(CLIENT *client, uint64_t block, bool full) {
	off_t *slot = g_hash_table_lookup(client->diffmap, &block);
	off_t diffoff;

	if(slot)
		return *slot;

	if(client->server->flags & F_SPARSE) {
		diffoff = (off_t)(block * DIFFPAGESIZE);
	} else {
		diffoff = lseek(client->difffile, 0, SEEK_END);
		if(diffoff < 0)
			return -1;
	}
	if(!full) {
		if(cow_copy_original(client, block, diffoff) < 0)
			return -1;
	}
	uint64_t *keyp = g_new(uint64_t, 1);
	off_t *valp = g_new(off_t, 1);
	*keyp = block;
	*valp = diffoff;
	g_hash_table_insert(client->diffmap, keyp, valp);
	return diffoff;
}
