```c
/**
 * Copy the original contents of a block from the master file into the
 * diff file, so that a partially-written block remains complete in the
 * diff file.
 *
 * Must be called with the export lock held for writing.
 *
 * @param client The client we're serving for
 * @param block The block number to copy
 * @param diffoff The offset in the diff file where the block is stored
 * @return 0 on success, -1 on error
 **/
static int cow_copy_original(CLIENT *client, uint64_t block, off_t diffoff) {
	char buf[DIFFPAGESIZE];
	off_t a = (off_t)(block * DIFFPAGESIZE);
	size_t blocklen = DIFFPAGESIZE;
	ssize_t ret;

	if((uint64_t)a + blocklen > client->exportsize)
		blocklen = client->exportsize - a;
	while(blocklen > 0) {
		ret = rawexpread(a, buf, blocklen, client);
		if(ret <= 0)
			return -1;
		a += ret;
		blocklen -= ret;
		char *wbuf = buf;
		size_t wlen = ret;
		while(wlen > 0) {
			ssize_t w = pwrite(client->difffile, wbuf, wlen, diffoff);
			if(w <= 0)
				return -1;
			wbuf += w;
			wlen -= w;
			diffoff += w;
		}
	}
	return 0;
}
```

