expcowwrite:

```c
/**
 * Write an amount of bytes at a given offset into the copy-on-write
 * diff file, leaving the master file alone. Data is written in
 * DIFFPAGESIZE-sized chunks; blocks that are written for the first
 * time are allocated in the diff file first.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return 0 on success, nonzero on failure
 **/
int expcowwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	while(len > 0) {
		off_t blockoff = a % DIFFPAGESIZE;
		uint64_t block = a / DIFFPAGESIZE;
		size_t chunk = len;
		off_t diffoff;
		ssize_t w;

		if(chunk > (size_t)(DIFFPAGESIZE - blockoff))
			chunk = DIFFPAGESIZE - blockoff;

		DEBUG("(WRITE to diff fd %d offset %llu len %u), ", client->difffile, (unsigned long long)a, (unsigned int)chunk);

		pthread_rwlock_wrlock(&client->export_lock);
		diffoff = cow_get_slot(client, block, chunk == DIFFPAGESIZE);
		if(diffoff >= 0) {
			off_t pos = diffoff + blockoff;
			size_t done = 0;
			while(done < chunk) {
				w = pwrite(client->difffile, buf + done, chunk - done, pos);
				if(w <= 0) {
					diffoff = -1;
					break;
				}
				done += w;
				pos += w;
			}
		}
		pthread_rwlock_unlock(&client->export_lock);
		if(diffoff < 0)
			return -1;

		a += chunk;
		buf += chunk;
		len -= chunk;
	}

	if(client->server->flags & F_SYNC) {
		return fsync(client->difffile);
	} else if(fua) {
		return fdatasync(client->difffile);
	}
	return 0;
}
```

