/**
 * Set up copy-on-write for this client's connection: create the diff
 * file that will catch all writes for the duration of the connection,
 * so that the master file is left alone. If the cowdir option is set,
 * the diff file is created there, otherwise it is created in the same
 * directory as the master file.
 *
 * @param client information on the client which we want to setup
 * copy-on-write for. client->exportsize must be set.
 * @return true on success, false on failure
 **/
static bool setup_cow(CLIENT* client) {
        _cleanup_g_free_ gchar *dir = NULL;
        _cleanup_g_free_ gchar *base = NULL;
        const gchar *cowdir = client->server->cowdir;
        int n = 0;

        /* a client may select an export more than once during
         * negotiation; drop any state left over from a previous attempt */
        cleanup_cow(client);
        base = g_path_get_basename(client->exportname);
        if(!cowdir) {
                dir = g_path_get_dirname(client->exportname);
                cowdir = dir;
        }
        do {
                g_free(client->difffilename);
                client->difffilename = g_strdup_printf("%s/%s.%d-%d.diff",
                                cowdir, base, (int)getpid(), n++);
                client->difffile = open(client->difffilename,
                                O_RDWR | O_CREAT | O_EXCL, 0600);
        } while(client->difffile == -1 && errno == EEXIST);
        if(client->difffile == -1) {
                err_nonfatal("Could not create copy-on-write file: %m");
                g_free(client->difffilename);
                client->difffilename = NULL;
                return false;
        }
        if(client->server->flags & F_SPARSE) {
                if(ftruncate(client->difffile, client->exportsize) < 0) {
                        err_nonfatal("Could not resize copy-on-write file: %m");
                        close(client->difffile);
                        client->difffile = -1;
                        unlink(client->difffilename);
                        g_free(client->difffilename);
                        client->difffilename = NULL;
                        return false;
                }
        }
        client->diffmap = g_hash_table_new_full(g_int64_hash, g_int64_equal,
                        g_free, g_free);
        msg(LOG_INFO, "Copy-on-write for this connection goes to %s",
                        client->difffilename);
        return true;
}

